/*
 * ESP32 NTP Clock on LCD I2C - Indian Standard Time (IST)
 * Connects to Wi-Fi, fetches UTC time via ntpEpoch(),
 * applies UTC+5:30 offset, and displays HH:MM:SS on a 16x2 LCD.
 *
 * Wiring: LCD VCC -> 3V3/5V, GND -> GND, SDA -> D21, SCL -> D22
 */

#include <WiFi.h>
#include <Wire.h>
#include <LiquidCrystal_I2C.h>

const char* ssid     = "ArduSimNet";
const char* password = "simulator";

// IST is UTC +5:30 (5*3600 + 30*60 = 19800 seconds)
const long istOffsetSec = 19800;

LiquidCrystal_I2C lcd(0x27, 16, 2);

void setup() {
  Serial.begin(115200);
  lcd.init();
  lcd.backlight();

  lcd.setCursor(0, 0);
  lcd.print("Connecting...");
  Serial.println("Connecting to Wi-Fi...");

  WiFi.begin(ssid, password);
  while (WiFi.status() != WL_CONNECTED) {
    delay(300);
    Serial.print(".");
  }
  Serial.println();
  Serial.print("IP: ");
  Serial.println(WiFi.localIP());

  lcd.clear();
  lcd.setCursor(0, 0);
  lcd.print("   NTP Clock");
  lcd.setCursor(0, 1);
  lcd.print(WiFi.localIP());
  delay(1500);
}

void loop() {
  // Fetch UTC epoch and apply IST offset
  unsigned long epoch = ntpEpoch() + istOffsetSec;

  int hours   = (epoch % 86400) / 3600;
  int minutes = (epoch % 3600)   / 60;
  int seconds = epoch % 60;

  lcd.setCursor(0, 0);
  lcd.print("  NTP Time (IST) ");

  lcd.setCursor(0, 1);
  lcd.print("    ");
  if (hours < 10) lcd.print("0");
  lcd.print(hours);
  lcd.print(":");
  if (minutes < 10) lcd.print("0");
  lcd.print(minutes);
  lcd.print(":");
  if (seconds < 10) lcd.print("0");
  lcd.print(seconds);
  lcd.print("    ");

  Serial.print("IST Time: ");
  if (hours < 10) Serial.print("0");
  Serial.print(hours);
  Serial.print(":");
  if (minutes < 10) Serial.print("0");
  Serial.print(minutes);
  Serial.print(":");
  if (seconds < 10) Serial.print("0");
  Serial.println(seconds);

  delay(1000);
}
